<template><div class="catalog-pictures" v-if="editable||images.length||queue.length||error"><div v-if="editable" class="caption">{{kind==='SHOP'?'店铺封面':'展示图片'}}（选填）</div><div class="gallery" :class="{compact}"><figure v-for="im in images" :key="im.id"><img :src="im.src" :alt="kind==='SHOP'?'店铺封面':'展示图片'" loading="lazy"/><button v-if="editable" type="button" :disabled="busy" @click.stop="remove(im.id)">移除</button></figure><figure v-for="im in queue" :key="im.key"><img :src="im.src" alt="待上传图片"/><button type="button" :disabled="busy" @click.stop="drop(im.key)">移除</button></figure></div><template v-if="editable"><input v-if="images.length+queue.length<max" aria-label="选择图片" type="file" accept="image/jpeg,image/png" :multiple="max>1" :disabled="busy" @change="pick"/><button v-if="queue.length && target" type="button" :disabled="busy" @click="retry">{{busy?'上传中…':'上传所选图片'}}</button></template><small v-if="error" role="alert">{{error}}</small></div></template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {apiClient,getApi,unwrapApiResponse} from '@/api/client';import {useAuthStore} from '@/stores/auth'
const props=defineProps<{kind:string;objectId?:number|null;editable?:boolean;compact?:boolean}>();const emit=defineEmits<{changed:[]}>(),auth=useAuthStore(),max=computed(()=>props.kind==='SHOP'?1:3),target=ref(0),images=ref<{id:number;src:string}[]>([]),queue=ref<{src:string;file:File;key:string}[]>([]),busy=ref(false),error=ref('');let generation=0,readSeq=0;const path=(id:number)=>`/catalog-media/${props.kind}/${id}`;const revoke=(s:string)=>{if(s.startsWith('blob:'))URL.revokeObjectURL(s)}
function clearImages(){images.value.forEach(x=>revoke(x.src));images.value=[]}function clear(){generation++;readSeq++;clearImages();queue.value.forEach(x=>revoke(x.src));queue.value=[];error.value='';busy.value=false}
async function load(){const id=target.value,v=++readSeq;if(!id)return;const result:{id:number;src:string}[]=[];try{const all=await getApi<{id:number;published:boolean}[]>(path(id));for(const im of props.compact?all.slice(0,1):all){if(v!==readSeq)break;const url=path(id)+'/'+im.id;const src=im.published?'/api'+url:URL.createObjectURL((await apiClient.get<Blob>(url,{responseType:'blob'})).data);result.push({id:im.id,src})}if(v!==readSeq){result.forEach(x=>revoke(x.src));return}clearImages();images.value=result}catch(e){result.forEach(x=>revoke(x.src));if(v===readSeq&&props.editable)error.value='图片暂时无法加载'}}
watch([()=>props.kind,()=>props.objectId,()=>auth.token],([k,id,t],old)=>{const n=Number(id)||0;const firstSave=old&&k===old[0]&&t===old[2]&&!Number(old[1])&&n>0;if(!firstSave)clear();target.value=n;if(n)void load()},{immediate:true,flush:'sync'});onBeforeUnmount(clear)
function pick(e:Event){const el=e.target as HTMLInputElement,files=[...(Array.from(el.files||[]))];el.value='';if(files.length+images.value.length+queue.value.length>max.value||files.some(f=>!['image/png','image/jpeg'].includes(f.type)||f.size>5*1024*1024||!f.size)){error.value=`最多 ${max.value} 张 JPG 或 PNG，每张不超过 5 MiB`;return}queue.value.push(...files.map(file=>({file,key:crypto.randomUUID(),src:URL.createObjectURL(file)})));error.value=''}
function drop(key:string){const file=queue.value.find(x=>x.key===key);if(file)revoke(file.src);queue.value=queue.value.filter(x=>x.key!==key)}
async function saveTo(id:number){if(!id||!queue.value.length)return;if(busy.value)throw Error('图片正在上传');const v=generation;target.value=id;busy.value=true;error.value='';try{for(const im of queue.value.slice()){if(v!==generation)throw Error('页面已变化');const b=new FormData();b.append('clientRequestId',im.key);b.append('file',im.file);unwrapApiResponse((await apiClient.post(path(id),b,{timeout:60000})).data);if(v!==generation)throw Error('页面已变化');drop(im.key)}await load();if(v===generation)emit('changed')}catch(e){if(v===generation)error.value='资料已保存，图片未传完，可重试';throw e}finally{if(v===generation)busy.value=false}}
async function retry(){try{await saveTo(target.value)}catch{/* inline retry */}}
async function remove(id:number){if(busy.value)return;const v=generation;busy.value=true;try{unwrapApiResponse((await apiClient.delete(path(target.value)+'/'+id)).data);if(v===generation){await load();emit('changed')}}catch{if(v===generation)error.value='移除失败，请重试'}finally{if(v===generation)busy.value=false}}
defineExpose({saveTo,reset:clear})
</script><style scoped>.gallery{display:flex;flex-wrap:wrap;gap:.45rem}.gallery figure{margin:0;display:grid;max-width:100%}.gallery img{width:9rem;max-width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:.45rem}.compact img{width:100%;max-height:10rem}.catalog-pictures input{max-width:100%}.catalog-pictures small{display:block;color:#8a491d}</style>
